/** All 350 translations for zizhitongjian ch.159 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第159卷", literal: "Comprehensive Mirror in Aid of Governance, Volume 159", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 159" },
  { zh: "【梁紀十五】　起旃蒙赤奮若，盡柔兆攝提格，凡二年。", literal: "[Liang Records 15] From Zhanmeng Chifenruo through Rouzhao Shotige; two years in all.", idiomatic: "[Liang Records 15] The span runs from Zhanmeng Chifenruo through Rouzhao Shotige—two years in all." },
  { zh: "高祖武皇帝十五大同十一年（", literal: "Great Ancestor Emperor Wu, fifteenth year of the Datong era (", idiomatic: "Emperor Wu of Liang, fifteenth year of Datong (" },
  { zh: "乙丑，公元五四五年）", literal: "yichou, 545 CE)", idiomatic: "yichou, AD 545)" },
  { zh: "春，正月，丙申，東魏遣兼散騎常侍李獎來聘。", literal: "In spring, the first month, on bingchen, Eastern Wei sent Acting Palace Attendant Li Jiang as envoy.", idiomatic: "In spring, the first month, on bingchen, Eastern Wei sent Acting Palace Attendant Li Jiang on a friendly mission." },
  { zh: "東魏儀同爾朱文暢與丞相司馬任冑、都督鄭仲禮等，謀因正月望夜觀打簇戲作亂，殺丞相歡，奉文暢為主。", literal: "Eastern Wei Yitong Erzhu Wenchang, the chancellor's marshal Ren Zhou, and Commissioner Zheng Zhongli and others plotted to use the first-month full-moon night, while watching fireworks, to rebel—kill Chancellor Huan and set Wenchang up as ruler.", idiomatic: "Eastern Wei's Erzhu Wenchang, Chancellor Gao Huan's marshal Ren Zhou, Commissioner Zheng Zhongli, and others plotted a Lantern-night rising during the fireworks show: kill Gao Huan and make Wenchang ruler." },
  { zh: "事洩，皆死。", literal: "The plot leaked; all were executed.", idiomatic: "The plot leaked; all were executed." },
  { zh: "文暢，榮之子也；", literal: "Wenchang was Erzhu Rong's son.", idiomatic: "Wenchang was Erzhu Rong's son." },
  { zh: "其姊，敬宗之後，及仲禮姊大車，皆為歡妾，有寵，故其兄弟皆不坐。", literal: "His sister, a descendant of Jingzong, and Zhongli's elder sister Dache were all Huan's favored concubines, so their brothers were not punished.", idiomatic: "His sister, a descendant of Jingzong, and Zhongli's elder sister Dache were all Gao Huan's favored concubines, so their brothers went unpunished." },
  { zh: "歡上書言：「并州，軍器所聚，動須女功，請置宮以處配沒之口；", literal: "Huan memorialized: \"Bingzhou is where military stores gather; work constantly needs women's labor. I ask that a palace be set up to house persons assigned from confiscations;", idiomatic: "Gao Huan memorialized: \"Bingzhou is where the arsenals gather and women's labor is always needed. I ask that a palace be established for persons taken in confiscations;" },
  { zh: "又納吐谷渾之女以招懷之。", literal: "Also take a Tuyuhun woman in marriage to win them over.", idiomatic: "and that a Tuyuhun woman be taken in marriage to win them over." },
  { zh: "」丁未，置晉陽宮。", literal: "\" On dingwei the Jinyang Palace was established.", idiomatic: "\" On dingwei the Jinyang Palace was established." },
  { zh: "二月，庚申，東魏主納吐谷渾可汗從妹為容華。", literal: "In the second month, on gengshen, the Eastern Wei ruler took a cousin of the Tuyuhun khan as Ronghua.", idiomatic: "In the second month, on gengshen, the Eastern Wei emperor took a cousin of the Tuyuhun khan as Ronghua." },
  { zh: "魏丞相泰遣酒泉胡安諾槃陀始通使於突厥。", literal: "Western Wei Chancellor Tai sent the Jiuquan Hu Anuopantuo as the first envoy to the Turks.", idiomatic: "Yuwen Tai sent the Jiuquan Hu Anuopantuo as the first envoy to the Turks." },
  { zh: "突厥本西方小國，姓阿史那氏，世居金山之陽，為柔然鐵工。", literal: "The Turks were originally a small state of the west, surname Ashina; for generations they lived south of Gold Mountain and were ironworkers for the Rouran.", idiomatic: "The Turks were originally a small western people of the Ashina clan; for generations they lived south of Gold Mountain and smithied iron for the Rouran." },
  { zh: "至其酋長土門，始強大，頗侵魏西邊。", literal: "Under their chieftain Tumen they first grew strong and raided Western Wei's western border.", idiomatic: "Under their chieftain Tumen they first grew strong and raided Western Wei's western marches." },
  { zh: "安諾槃陀至，其國人皆喜曰：「大國使者至，吾國其將興矣！", literal: "When Anuopantuo arrived, the people of the state all rejoiced and said: \"An envoy of a great state has come—our state is about to rise!", idiomatic: "When Anuopantuo arrived, the Turks rejoiced: \"An envoy of a great power has come—our realm will rise!" },
  { zh: "三月，乙未，東魏丞相歡入朝於鄴，百官迎於紫陌。", literal: "In the third month, on yimao, Eastern Wei Chancellor Huan entered court at Ye; the hundred officials welcomed him at Zimo.", idiomatic: "In the third month, on yimao, Gao Huan entered court at Ye; the officials welcomed him at Zimo." },
  { zh: "歡握崔暹手而勞之曰：「往日朝廷豈無法官，莫肯糾劾。", literal: "Huan took Cui Xuan's hand and praised him: \"In the past the court certainly had law officers—none would impeach.", idiomatic: "Gao Huan took Cui Xuan's hand and praised him: \"The court always had law officers—none would impeach." },
  { zh: "中尉盡心徇國，不避豪強，遂使遠邇肅清。", literal: "The Commandant gave his heart to the state and did not avoid the powerful, so far and near were purified.", idiomatic: "The Commandant gave his heart to the state and did not spare the powerful, until far and near were clean." },
  { zh: "衝鋒陷陣，大有其人；", literal: "Men who charge breaches and break arrays—there are many such;", idiomatic: "Men who charge breaches and break arrays—there are many;" },
  { zh: "當官正色，今始見之。", literal: "to hold office with an upright countenance—only now do I see it.", idiomatic: "but to hold office with an upright countenance—only now do I see it." },
  { zh: "富貴乃中尉自取，高歡父子無以相報。", literal: "Wealth and rank the Commandant takes for himself; Gao Huan father and son have nothing with which to repay him.", idiomatic: "Wealth and rank the Commandant earns himself; Gao Huan and his sons have no way to repay him." },
  { zh: "」賜暹良馬。", literal: "\" He gave Xuan a fine horse.", idiomatic: "\" He gave Xuan a fine horse." },
  { zh: "暹拜，馬驚走，歡親擁之，授以轡。", literal: "Xuan bowed; the horse startled and bolted; Huan personally steadied him and handed him the reins.", idiomatic: "Xuan bowed; the horse bolted; Gao Huan himself caught him and gave him the reins." },
  { zh: "東魏主宴於華林園，使歡擇朝廷公直者勸之酒；", literal: "The Eastern Wei ruler feasted at Hualin Garden and had Huan choose upright men of the court to toast him;", idiomatic: "The Eastern Wei emperor feasted at Hualin Garden and had Gao Huan choose upright courtiers to toast him;" },
  { zh: "歡降階跪曰：「唯暹一人可勸，並請以臣所射賜物千段賜之。", literal: "Huan descended the steps, knelt, and said: \"Only Xuan can toast; I also ask that the thousand lengths of my archery prizes be given him.", idiomatic: "Gao Huan came down the steps, knelt, and said: \"Only Xuan is fit to toast; I also ask that the thousand lengths of my archery prizes be given him." },
  { zh: "」高澄退，謂暹曰：「我尚畏羨，何況餘人！", literal: "\" Gao Cheng withdrew and said to Xuan: \"I still fear envy—how much more the rest!", idiomatic: "\" Gao Cheng withdrew and told Xuan: \"Even I still fear envy—how much more the rest!" },
  { zh: "」然暹中懷頗挾巧詐。", literal: "\" Yet Xuan inwardly harbored much crafty deceit.", idiomatic: "\" Yet Xuan inwardly carried a good deal of crafty deceit." },
  { zh: "初，魏高陽王斌有庶妹玉儀，不為其家所齒，為孫騰妓，騰又棄之；", literal: "Earlier, Western Wei Prince of Gaoyang Bin had a concubine-born sister Yuyi; her family disdained her; she became Sun Teng's courtesan, and Teng abandoned her;", idiomatic: "Earlier, Western Wei's Prince of Gaoyang, Bin, had a concubine-born sister Yuyi whom the family disdained; she became Sun Teng's courtesan, and Teng cast her off;" },
  { zh: "高澄遇諸塗，悅而納之，遂有殊寵，封琅邪公主。", literal: "Gao Cheng met her on the road, was delighted, and took her in; she won special favor and was made Princess of Langye.", idiomatic: "Gao Cheng met her on the road, was taken with her, and took her in; she won special favor and was made Princess of Langye." },
  { zh: "澄謂崔季舒曰：「崔暹必造直諫，我亦有以待之。", literal: "Cheng told Cui Jishu: \"Cui Xuan is sure to offer blunt remonstrance; I too have a way to wait for him.", idiomatic: "Cheng told Cui Jishu: \"Cui Xuan is sure to remonstrate bluntly; I have a way to wait for him too." },
  { zh: "」及暹咨事，澄不復假以顏色。", literal: "\" When Xuan came to consult on affairs, Cheng no longer showed him a pleasant face.", idiomatic: "\" When Xuan came to consult, Cheng no longer gave him a pleasant face." },
  { zh: "居三日，暹懷刺墜之於前。", literal: "After three days Xuan dropped a dagger before him.", idiomatic: "After three days Xuan let a dagger fall before him." },
  { zh: "澄問：「何用此為？", literal: "Cheng asked: \"What is this for?", idiomatic: "Cheng asked: \"What is this for?" },
  { zh: "」暹悚然曰：「未得通公主。", literal: "\" Xuan said fearfully: \"I have not yet gained access to the Princess.", idiomatic: "\" Xuan said fearfully: \"I have not yet been presented to the Princess." },
  { zh: "」澄大悅，把暹臂，入見之。", literal: "\" Cheng was greatly pleased, took Xuan's arm, and led him in to see her.", idiomatic: "\" Cheng was delighted, took Xuan's arm, and led him in to see her." },
  { zh: "季舒語人曰：「崔暹常忿吾佞，在大將軍前，每言叔父可殺；", literal: "Jishu told people: \"Cui Xuan always resented my flattery; before the Great General he often said my uncle should be killed;", idiomatic: "Jishu told others: \"Cui Xuan always hated my flattery; before the Great General he often said my uncle deserved death;" },
  { zh: "及其自作，乃過於吾。", literal: "when he did it himself, he surpassed me.", idiomatic: "when he did it himself, he outdid me." },
  { zh: "夏，五月，甲辰，東魏大赦。", literal: "In summer, the fifth month, on jiachen, Eastern Wei proclaimed a general amnesty.", idiomatic: "In summer, the fifth month, on jiachen, Eastern Wei proclaimed a general amnesty." },
  { zh: "魏王盟卒。", literal: "Western Wei Prince Meng died.", idiomatic: "Western Wei's Prince Meng died." },
  { zh: "晉氏以來，文章競為浮華，魏丞相泰欲革其弊。", literal: "Since the Jin house, writings vied in florid ornament; Western Wei Chancellor Tai wished to reform that evil.", idiomatic: "Since Jin times, writing had vied in florid ornament; Yuwen Tai wished to reform it." },
  { zh: "六月，丁巳，魏主饗太廟。", literal: "In the sixth month, on dingsi, the Western Wei ruler feasted the imperial temple.", idiomatic: "In the sixth month, on dingsi, the Western Wei emperor feasted at the imperial temple." },
  { zh: "泰命大行台度支尚書、領著作蘇綽作《大誥》，宣示群臣，戒以政事；", literal: "Tai ordered Grand Secretariat fiscal minister and concurrent historiographer Su Chuo to compose the \"Great Admonition,\" display it to the ministers, and warn them in state affairs;", idiomatic: "Yuwen Tai ordered Su Chuo, fiscal minister of the Grand Secretariat and concurrent historiographer, to compose the \"Great Admonition,\" display it to the ministers, and warn them on government;" },
  { zh: "仍命「自今文章皆依此體。", literal: "He also ordered: \"From now on all writings shall follow this style.", idiomatic: "He also ordered: \"From now on all writings shall follow this style." },
  { zh: "上遣交州刺史楊瞟討李賁，以陳霸先為司馬；", literal: "The emperor sent Jiaozhou Inspector Yang Biao against Li Ben and made Chen Baxian marshal;", idiomatic: "The Liang emperor sent Jiaozhou Inspector Yang Biao against Li Ben and made Chen Baxian marshal;" },
  { zh: "命定州刺史蕭勃會瞟於西江。", literal: "He ordered Dingzhou Inspector Xiao Bo to join Biao at Xijiang.", idiomatic: "He ordered Dingzhou Inspector Xiao Bo to join Biao at Xijiang." },
  { zh: "勃知軍士憚遠役，因詭說留瞟。", literal: "Bo knew the troops feared a long campaign and used deceit to detain Biao.", idiomatic: "Bo knew the troops dreaded a distant campaign and used deceit to hold Biao back." },
  { zh: "瞟集諸將問計，霸先曰：「交趾叛換，罪由宗室，遂使溷亂數州，逋誅累歲。", literal: "Biao gathered the generals to ask counsel; Baxian said: \"Jiaozhi rebels and shifts allegiance; the fault lies with the imperial clan, and several provinces have been thrown into turmoil while punishment has been evaded for years.", idiomatic: "Biao gathered the generals for counsel. Baxian said: \"Jiaozhi rebels; the fault lies with the imperial clan, and several provinces have been in turmoil while the court has failed to punish for years." },
  { zh: "定州欲偷安目前，不顧大計。", literal: "Dingzhou wishes ease for the moment and does not care for the great plan.", idiomatic: "Dingzhou wants comfort for the moment and ignores the larger plan." },
  { zh: "節下奉辭伐罪，當死生以之。", literal: "Your command bears the mandate to punish crime—we should stake life and death on it.", idiomatic: "Your command bears the mandate to punish crime—we should stake our lives on it." },
  { zh: "豈可逗撓不進，長寇沮眾也！", literal: "How can we hesitate and not advance, nourishing the bandit and discouraging the host!", idiomatic: "How can we hang back and not advance, feeding the rebel and breaking the army's heart!" },
  { zh: "」遂勒兵先發。", literal: "\" He then led the troops out first.", idiomatic: "\" He then led the troops out first." },
  { zh: "瞟以霸先為前鋒。", literal: "Biao made Baxian vanguard.", idiomatic: "Biao made Baxian his vanguard." },
  { zh: "至交州，賁帥眾三萬拒之，敗於朱鳶，又敗於蘇歷江口。", literal: "When they reached Jiaozhou, Ben commanded thirty thousand men to resist; he was defeated at Zhuyuan and again at the mouth of the Suli River.", idiomatic: "At Jiaozhou, Ben led thirty thousand to resist; he was beaten at Zhuyuan and again at the mouth of the Suli River." },
  { zh: "賁奔嘉寧城，諸軍進圍之。", literal: "Ben fled to Jianing city; the armies advanced to besiege it.", idiomatic: "Ben fled to Jianing; the armies advanced to besiege it." },
  { zh: "勃，昺之子也。", literal: "Bo was the son of Biao.", idiomatic: "Bo was the son of Biao." },
  { zh: "魏與柔然頭兵可汗謀連兵伐東魏，丞相歡患之，遣行台郎中杜弼使於柔然，為世子澄求婚。", literal: "Western Wei and Rouran Khan Toubing plotted a joint attack on Eastern Wei; Chancellor Huan was troubled and sent Secretariat Lang Du Bi to the Rouran to seek a bride for heir Cheng.", idiomatic: "Western Wei and the Rouran khan Toubing plotted a joint attack on Eastern Wei. Gao Huan, alarmed, sent Secretariat Lang Du Bi to the Rouran to seek a bride for heir Cheng." },
  { zh: "頭兵曰：「高王自娶則可。", literal: "Toubing said: \"If King Gao takes her himself, that will do.", idiomatic: "Toubing said: \"If King Gao takes her himself, very well." },
  { zh: "」歡猶豫未決。", literal: "\" Huan hesitated and could not decide.", idiomatic: "\" Gao Huan hesitated." },
  { zh: "婁妃曰：「國家大計，願勿疑也。", literal: "Consort Lou said: \"This is the great plan of the state—pray do not doubt.", idiomatic: "Consort Lou said: \"This is the state's great plan—do not doubt." },
  { zh: "」世子澄、尉景亦勸之。", literal: "\" Heir Cheng and Wei Jing also urged him.", idiomatic: "\" Heir Cheng and Wei Jing also urged him." },
  { zh: "歡乃遣鎮南將軍慕容儼聘之，號曰蠕蠕公主。", literal: "Huan then sent Suppressing-the-South General Murong Yan to betroth her, titled Rouran Princess.", idiomatic: "Gao Huan then sent Murong Yan, Suppressing-the-South General, to betroth her as the Rouran Princess." },
  { zh: "秋，八月，歡親迎於下館。", literal: "In autumn, the eighth month, Huan personally welcomed her at Xiaguan.", idiomatic: "In autumn, the eighth month, Gao Huan personally welcomed her at Xiaguan." },
  { zh: "公主至，婁妃避正室以處之；", literal: "When the princess arrived, Consort Lou vacated the main chamber to house her;", idiomatic: "When the princess arrived, Consort Lou vacated the main chamber for her;" },
  { zh: "歡跪而拜謝，妃曰：「彼將覺之，願絕勿顧。", literal: "Huan knelt and thanked her; the consort said: \"She will notice—pray cut off all attention.", idiomatic: "Gao Huan knelt to thank her; the consort said: \"She will notice—cut off all attention." },
  { zh: "」頭兵使其弟禿突佳來送女，且報聘；", literal: "\" Toubing sent his brother Tutujia to escort his daughter and return the visit;", idiomatic: "\" Toubing sent his brother Tutujia to escort his daughter and return the visit;" },
  { zh: "仍戒曰：「待見外孫乃歸。", literal: "He also warned: \"Wait until you see the grandson before returning.", idiomatic: "He also warned: \"Do not return until you have seen your grandson." },
  { zh: "」公主性嚴毅，終身不肯華言。", literal: "\" The princess was stern by nature and all her life refused to speak Chinese.", idiomatic: "\" The princess was stern by nature and all her life refused to speak Chinese." },
  { zh: "歡嘗病，不得往，禿突佳怨恚，歡輿疾就之。", literal: "Huan once fell ill and could not visit; Tutujia resented it; Huan rode in a carriage while ill to see him.", idiomatic: "Gao Huan once fell ill and could not visit; Tutujia was resentful; Gao Huan rode out while ill to see him." },
  { zh: "冬，十月，乙未，詔有罪者復聽入贖。", literal: "In winter, the tenth month, on yimao, an edict allowed criminals again to redeem punishment.", idiomatic: "In winter, the tenth month, on yimao, an edict again allowed criminals to buy off punishment." },
  { zh: "東魏遣中書舍人尉瑾來聘。", literal: "Eastern Wei sent Secretariat Attendant Yu Jin as envoy.", idiomatic: "Eastern Wei sent Secretariat Attendant Yu Jin on a friendly mission." },
  { zh: "乙未，東魏丞相歡請釋邙山俘囚桎梏，配以民間寡婦。", literal: "On yimao, Eastern Wei Chancellor Huan asked to release the Mangshan prisoners from shackles and match them with widows from among the people.", idiomatic: "On yimao, Gao Huan asked to free the Mangshan prisoners from shackles and give them widows from among the people." },
  { zh: "十二月，東魏以侯景為司徒，中書令韓軌為司空；", literal: "In the twelfth month, Eastern Wei made Hou Jing Minister over the Masses and Han Gui Minister of Works;", idiomatic: "In the twelfth month, Eastern Wei made Hou Jing Minister over the Masses and Han Gui Minister of Works;" },
  { zh: "戊子，以孫騰錄尚書事。", literal: "On wuzi, Sun Teng was made Director of the Masters of Writing.", idiomatic: "On wuzi, Sun Teng was made Director of the Masters of Writing." },
  { zh: "魏築圜丘於城南。", literal: "Western Wei built a Round Mound south of the city.", idiomatic: "Western Wei built a Round Mound south of the city." },
  { zh: "散騎常侍賀琛啟陳四事：其一以為「今北邊稽服，正是生聚教議之時，而天下戶口減落，關外彌甚。", literal: "Palace Attendant He Chen memorialized on four matters. The first held that \"now the north has submitted—it is exactly the time to gather the people and teach and deliberate—yet household registers throughout the land are falling, and beyond the passes the loss is worse still.", idiomatic: "Palace Attendant He Chen submitted four memorials. The first argued that \"with the north now subdued, this should be a time to gather people and teach—but registers are shrinking everywhere, and beyond the passes the loss is worse." },
  { zh: "郡不堪州之控總，縣不堪郡之裒削，更相呼擾，惟事征斂。", literal: "Commanderies cannot bear the provinces' control; counties cannot bear the commanderies' stripping; they call on one another in turmoil and do nothing but levy.", idiomatic: "Commanderies cannot bear provincial control; counties cannot bear commandery exactions; they harass one another and do nothing but levy." },
  { zh: "民不堪命，各務流移，此豈非牧守之過歟！", literal: "The people cannot bear their lot; each seeks to flee—are these not the faults of the shepherds of the people!", idiomatic: "The people cannot bear their lot and flee—is this not the fault of local officials!" },
  { zh: "東境戶口空虛，皆由使命繁數，窮幽極遠，無不皆至，每有一使，所屬搔擾，駑困邑宰，則拱手聽其漁獵，桀黠長吏，又因之重為貪殘，縱有廉平，郡猶掣肘。", literal: "The eastern marches are empty of households, all because missions are numerous: to the farthest corners, none are left unreached. With every envoy, the districts he touches are harassed; when the magistrate is worn down, he folds his hands and lets them plunder; when the chief is crafty, he uses them to be doubly greedy. Even if one is honest, the commandery still pulls his elbow.", idiomatic: "The east is hollowed out because envoys are too many—no corner too remote. Every envoy ravages his route; worn magistrates fold their hands while he plunders; crafty chiefs use him to plunder again. Even an honest man finds the commandery tugging his sleeve." },
  { zh: "如此，雖年降復業之詔，屢下蠲賦之恩，而民不得反其居也。", literal: "Thus, though year after year edicts recall people to their trades and amnesties on levies are issued again and again, the people cannot return home.", idiomatic: "So though edicts year after year call people home and tax relief is granted again and again, they cannot return." },
  { zh: "」其二以為「今天下守宰所以貪殘，良由風俗侈靡使之然也。", literal: "\" The second held that \"today the reason governors and magistrates are greedy and cruel is truly that extravagant custom makes them so.", idiomatic: "\" The second held that \"today's greedy magistrates are made so by extravagant custom." },
  { zh: "今之燕喜，相競誇豪，積果如丘陵，列餚同綺繡，露台之產，不週一燕之資，而賓主之間，裁取滿腹，未及下堂，已同臭腐。", literal: "At today's feasts they vie in boasting wealth: fruit piled like hills, dishes set out like brocade; the yield of a terrace garden does not suffice for one banquet's cost, yet between host and guest they take only a full belly—before leaving the hall it is all rot.", idiomatic: "At feasts they vie in display: fruit heaped like hills, dishes like brocade; a terrace garden's yield will not pay for one banquet, yet host and guest eat only their fill—before they leave the hall it is rot." },
  { zh: "又，畜妓之夫，無有等秩，為吏牧民者，致貲巨億，罷歸之日，不支數年，率皆盡於燕飲之物、歌謠之具。", literal: "Again, men who keep courtesans have no rank limit; those who govern the people amass hundreds of millions, and the day they leave office they cannot last a few years—all is spent on feasting and on songs and music.", idiomatic: "Men who keep courtesans know no rank; officials who rule the people amass fortunes, and within years of leaving office it is all gone on feasts and music." },
  { zh: "所費事等丘山，為歡止在俄頃，乃更追恨向所取之少；", literal: "What is spent equals mountains; the pleasure lasts only a moment—then they regret having taken too little before;", idiomatic: "They spend like mountains; the joy lasts a moment—then they regret they took too little before;" },
  { zh: "如復傅翼，增其搏噬，一何悖哉！", literal: "give them wings again and they bite all the harder—how perverse!", idiomatic: "give them wings and they bite harder—how perverse!" },
  { zh: "其餘淫侈，著之凡百，習以成俗，日見滋甚。", literal: "The rest of debauchery, set out in a hundred ways, has become custom and grows worse daily.", idiomatic: "The rest of debauchery, in a hundred forms, has become custom and worsens daily." },
  { zh: "欲使人守廉白，安可得邪！", literal: "To wish men to keep integrity—how can it be obtained!", idiomatic: "To expect integrity—how can you have it!" },
  { zh: "誠宜嚴為禁制，導以節儉，糾奏浮華，變其耳目。", literal: "It is truly fitting to forbid this strictly, guide them by frugality, impeach florid display, and change what meets their eyes.", idiomatic: "Forbid it strictly, guide by frugality, impeach display, and change what they see." },
  { zh: "夫失節之嗟，亦民所自患，正恥不能及群，故勉強而為之；", literal: "The sigh at lost restraint is also what the people themselves suffer from—they are ashamed not to keep up with the crowd and so force themselves to it;", idiomatic: "People suffer from lost restraint too—they are ashamed not to keep up and force themselves;" },
  { zh: "苟以淳素為先，足正雕流之弊矣。", literal: "if simplicity comes first, it is enough to correct the evil of carved display.", idiomatic: "put simplicity first and you can correct carved display." },
  { zh: "」其三以為「陛下憂念四海，不憚勤勞，至於百司，莫不奏事。", literal: "\" The third held that \"Your Majesty cares for the four seas and does not shrink from toil; down to the hundred offices, none fails to memorialize.", idiomatic: "\" The third held that \"Your Majesty cares for all under heaven and toils without shrinking; every office memorializes." },
  { zh: "但斗筲之人，既得伏奏帷扆，便欲詭競求進，不論國之大體，心存明恕；", literal: "But petty men, once they can memorialize before the curtain, wish to compete by trickery for advancement; they do not discuss the great body of the state or keep magnanimity in mind;", idiomatic: "But petty men, once they can speak before the curtain, compete by tricks; they ignore the state's great body and forget magnanimity;" },
  { zh: "惟務吹毛求疵，擘肌分理，以深刻為能，以繩逐為務。", literal: "they only pursue splitting hairs and dividing fibers, taking harshness as ability and driving people with the rope.", idiomatic: "they split hairs and divide fibers, take harshness for talent, and drive people with the rope." },
  { zh: "跡雖似於奉公，事更成其威福，犯罪者多，巧避滋甚，長弊增奸，實由於此。", literal: "The trace seems to serve the public, but the affair only increases their power and profit; criminals multiply and clever evasions grow—long abuses and added treachery truly come from this.", idiomatic: "It looks like public service but only swells their power; crime multiplies and evasion grows—long abuse and added treachery come from this." },
  { zh: "誠願責其公平之效，黜其讒慝之心，則下安上謐，無徼幸之患矣。", literal: "I truly wish to demand their effect in fairness and dismiss their hearts of slander and malice; then below will be secure and above tranquil, with no hope of luck.", idiomatic: "Demand fairness, dismiss malice—then below is secure and above tranquil, without lucky gambles." },
  { zh: "」其四以為「今天下無事，而猶日不暇給，宜省事、息費，事省則民養，費息則財聚。", literal: "\" The fourth held that \"today the realm is at peace, yet there is still no leisure from day to day; affairs should be reduced and expenses stilled—when affairs are reduced the people are nourished; when expenses are stilled wealth gathers.", idiomatic: "\" The fourth held that \"the realm is at peace yet there is no leisure; reduce affairs and still expenses—reduce affairs and the people are fed; still expenses and wealth gathers." },
  { zh: "應內省職掌各檢所部：凡京師治、署、邸、肆及國容、戎備，四方屯、傳、邸治，有所宜除，除之，有所宜減，減之；", literal: "Within, each office should inspect its charge: all capital administration, offices, lodges, markets, state regalia, and military readiness; all frontier stations, posts, and lodge administration—what should be abolished, abolish; what should be reduced, reduce;", idiomatic: "Each office should inspect its charge: capital offices, lodges, markets, regalia, armaments; frontier posts and stations—abolish what should go, reduce what should shrink;" },
  { zh: "興造有非急者，徵求有可緩者，皆宜停省，以息費休民。", literal: "construction that is not urgent and levies that can be delayed should all be halted to still expense and rest the people.", idiomatic: "halt non-urgent construction and delayable levies to still expense and rest the people." },
  { zh: "故畜其財者，所以大用之也；", literal: "Thus to store wealth is to use it greatly;", idiomatic: "Store wealth to use it greatly;" },
  { zh: "養其民者，所以大役之也。", literal: "to nourish the people is to employ them greatly.", idiomatic: "nourish the people to employ them greatly." },
  { zh: "若言小事不足害財，則終年不息矣；", literal: "If one says small matters cannot harm wealth, then there is no ceasing year round;", idiomatic: "If you say small matters cannot harm wealth, there is no ceasing all year;" },
  { zh: "以小役不足妨民，則終年不止矣。", literal: "if small corvée cannot harm the people, then there is no stopping year round.", idiomatic: "if small corvée cannot harm the people, there is no stopping all year." },
  { zh: "如此，則難可以語富強而圖遠大矣。", literal: "Thus it is hard to speak of enriching the state and strong armies or plan for the far and great.", idiomatic: "Then you cannot speak of enriching the state, strong armies, or far-reaching plans." },
  { zh: "啟奏，上大怒，召主書於前，口授敕書以責琛。", literal: "When the memorial was submitted, the emperor was greatly angered; he summoned the chief clerks before him and dictated an edict in person to reproach Chen.", idiomatic: "When the memorial arrived, the emperor was furious; he summoned the chief clerks and dictated an edict reproaching Chen." },
  { zh: "大指以為：「朕有天下四十餘年，公車讜言，日關聽覽，所陳之事，與卿不異，每苦倥傯，更增惛惑。", literal: "The main points held that: \"I have held the realm more than forty years; public and private remonstrance daily reaches my ears. What you state is no different from what I hear; I am only vexed by hurry and only grow more confused.", idiomatic: "The gist was: \"I have held the realm forty years; remonstrance reaches me daily. What you say I already hear—I am only vexed and grow more confused." },
  { zh: "卿不宜自同闒茸，止取名字，宣之行路，言『我能上事，恨朝廷之不用』。", literal: "You should not make yourself like the vulgar, take only a name, proclaim it on the road, and say, 'I can memorialize to the throne and regret that the court does not use me.'", idiomatic: "Do not act the vulgar partisan, make a name for yourself, and proclaim in the streets, 'I can memorialize to the throne—pity the court will not employ me.'" },
  { zh: "何不分別顯言：某刺史橫暴，某太守貪殘，尚書、蘭台某人奸猾，使者漁獵，並何姓名？", literal: "Why not plainly name them: such-and-such governor is violent, such-and-such prefect greedy, such-and-such Master of Writing or such-and-such Secretariat man crafty, such-and-such envoy plunders—what are their names?", idiomatic: "Why not name them plainly: which governor is violent, which prefect greedy, which minister or Secretariat man crafty, which envoy plunders—what are their names?" },
  { zh: "取與者誰？", literal: "Who gives and who takes?", idiomatic: "Who gives and who takes?" },
  { zh: "明言其事，得以誅黜，更擇材良。", literal: "State the affair plainly so they can be executed and removed, and choose new talent.", idiomatic: "State it plainly so they can be punished and better men chosen." },
  { zh: "又，士民飲食過差，若加嚴禁，密房曲屋，雲何可知？", literal: "Again, when gentry and people exceed in food and drink—if you add strict prohibition, in hidden rooms and inner chambers, how can you know?", idiomatic: "If gentry and people exceed in food and drink—strict prohibition in hidden rooms, how would you know?" },
  { zh: "倘家家搜檢，恐益增苛擾。", literal: "If you search every house, I fear you will only add harsh harassment.", idiomatic: "Search every house and you only add harassment." },
  { zh: "若指朝廷，我無此事。", literal: "If you mean the court— I have no such thing.", idiomatic: "If you mean the court—I have no such thing." },
  { zh: "昔之牲牢，久不宰殺，朝中會同，菜蔬而已；", literal: "Long ago the sacrificial oxen were not slaughtered for a long time; court gatherings used only vegetables;", idiomatic: "Long ago we stopped slaughtering sacrificial beasts; court gatherings use only vegetables;" },
  { zh: "若復減此，必有《蟋蟀》之譏。", literal: "if this is reduced further, there will surely be the reproach of the \"Crickets.\"", idiomatic: "reduce that further and you invite the reproach of the \"Crickets.\"" },
  { zh: "若以為功德事者，皆是園中之物，變一瓜為數十種，治一菜為數十味；", literal: "If you think merit and virtue affairs are all garden produce—one melon made into dozens of kinds, one dish into dozens of flavors—", idiomatic: "If you think merit feasts are only garden stuff—one melon into dozens of dishes, one vegetable into dozens of flavors—" },
  { zh: "以變故多，何損於事！", literal: "with so many changes, what harm to affairs!", idiomatic: "with so many changes, what harm is done!" },
  { zh: "「我自非公宴，不食國家之食，多歷年所；", literal: "\"I myself, unless it is a public feast, do not eat the state's food—many years now;", idiomatic: "\"Unless it is a public feast, I do not eat the state's food—many years now;" },
  { zh: "乃至宮人，亦不食國家之食。", literal: "down to the palace women, they too do not eat the state's food.", idiomatic: "even palace women do not eat the state's food." },
  { zh: "凡所營造，不關材官及以國匠，皆資雇藉以成其事。", literal: "All construction does not involve the materials office or state craftsmen; all is hired labor to complete the work.", idiomatic: "All my building uses hired labor, not the materials office or state craftsmen." },
  { zh: "勇怯不同，貪廉各用，亦非朝廷為之傅翼。", literal: "Brave and timid differ; greedy and clean each have their use—this too is not the court giving them wings.", idiomatic: "Brave and timid differ; greedy and honest each have their place—the court does not give them wings for that." },
  { zh: "卿以朝廷為悖，乃自甘之，當思致悖所以！", literal: "You take the court as perverse yet gladly accept it yourself—you should think what makes perverseness!", idiomatic: "You call the court perverse yet take your ease—you should ask what makes perverseness!" },
  { zh: "卿云『宜導之以節儉』，朕絕房室三十餘年，至於居處不過一床之地，雕飾之物不入於宮；", literal: "You say 'they should be guided by frugality'—I have closed off the inner quarters more than thirty years; my dwelling is no more than one bed's space; carved ornament does not enter the palace;", idiomatic: "You say guide by frugality—I have closed the inner quarters thirty years; my dwelling is one bed's space; carved ornament does not enter the palace;" },
  { zh: "受生不飲酒，不好音聲，所以朝中曲宴，未嘗奏樂，此群賢之所見也。", literal: "from birth I do not drink wine, I do not love sounds; therefore at court feasts music is never played—the assembled worthies have seen this.", idiomatic: "I do not drink, I do not love music; at court feasts there is no music—the worthies have seen it." },
  { zh: "朕三更出治事，隨事多少，事少午前得竟，事多日昃方食，日常一食，若晝若夜；", literal: "I rise at the third watch to handle affairs; as affairs are many or few, when few I finish before noon, when many I eat only at sundown; ordinarily one meal, day or night;", idiomatic: "I rise at the third watch; few affairs I finish before noon, many I eat at sundown—one meal, day or night;" },
  { zh: "昔要腹過於十圍，今之瘦削裁二尺餘，舊帶猶存，非為妄說。", literal: "once my belly was more than ten spans around; now my leanness is barely two feet and more; the old belt still remains—this is no empty claim.", idiomatic: "once my waist was ten spans; now I am barely two feet round—the old belt still proves it." },
  { zh: "為誰為之？", literal: "For whom did I do it?", idiomatic: "For whom?" },
  { zh: "救物故也。", literal: "To save living things.", idiomatic: "To save living things." },
  { zh: "「卿又曰『百司莫不奏事，詭競求進』，今不使外人呈事，誰屍其任！", literal: "\"You also say 'the hundred offices all memorialize and compete by trickery'—if outsiders are not allowed to present affairs, who bears the burden!", idiomatic: "\"You say every office memorializes and competes by tricks—if outsiders may not present affairs, who bears the burden!" },
  { zh: "專委之人，雲何可得？", literal: "To entrust it wholly to one man—how can he be obtained?", idiomatic: "Entrust all to one man—how can you have him?" },
  { zh: "古人云：『專聽生奸，獨任成亂。", literal: "The ancients said: 'Sole hearing breeds treachery; sole trust breeds chaos.", idiomatic: "The ancients said: \"Sole hearing breeds treachery; sole trust breeds chaos." },
  { zh: "』二世之委趙高，元後之付王莽，呼鹿為馬，又可法歟？", literal: "' The Second Emperor entrusted Zhao Gao; Yuanshi entrusted Wang Mang; calling a deer a horse—can that be taken as law?", idiomatic: "\" The Second Emperor entrusted Zhao Gao; Yuanshi entrusted Wang Mang—calling a deer a horse—is that law?" },
  { zh: "卿云『吹毛求疵』，復是何人？", literal: "You say 'splitting hairs'—who is it?", idiomatic: "You say \"splitting hairs\"—who?" },
  { zh: "『擘肌分理』，復是何事？", literal: "'Dividing fibers'—what affair is it?", idiomatic: "\"Dividing fibers\"—what affair?" },
  { zh: "治、署、邸、肆等，何者宜除？", literal: "Administration, offices, lodges, markets, and the like—which should be abolished?", idiomatic: "Which offices, lodges, and markets should go?" },
  { zh: "何者宜減？", literal: "Which should be reduced?", idiomatic: "Which should be cut?" },
  { zh: "何處興造非急？", literal: "Where is construction not urgent?", idiomatic: "Where is construction not urgent?" },
  { zh: "何處徵求可緩？", literal: "Where may levies be delayed?", idiomatic: "Where may levies wait?" },
  { zh: "各出其事，具以奏聞！", literal: "Set out each matter and memorialize in full!", idiomatic: "Set out each and memorialize in full!" },
  { zh: "富國強兵之術，息民省役之宜，並宜具列！", literal: "Methods to enrich the state and strengthen the army, and measures to rest the people and reduce corvée—all should be listed in full!", idiomatic: "List every method to enrich the state, strengthen the army, and rest the people!" },
  { zh: "若不具列，則是欺罔朝廷。", literal: "If you do not list them in full, you are deceiving the court.", idiomatic: "If you do not list them, you deceive the court." },
  { zh: "佇聞重奏，當復省覽，付之尚書，班下海內，庶惟新之美，復見今日。", literal: "I await your renewed memorial; I shall examine it again, deliver it to the Masters of Writing, and promulgate it throughout the realm—may the beauty of renewal appear again today.", idiomatic: "I await your renewed memorial, will examine it, send it to the Masters of Writing, and promulgate it—may renewal appear again today." },
  { zh: "」琛但謝過而已，不敢復言。", literal: "\" Chen only apologized and did not dare speak again.", idiomatic: "\" Chen only apologized and dared not speak again." },
  { zh: "上為孝教慈恭儉，博學能文，陰陽、卜筮、騎射、聲律、草隸、圍棋，無不精妙。", literal: "The emperor was filial, taught kindness, respectful and frugal, broadly learned and able in writing; yin-yang, divination, riding, archery, pitch, chess, clerical script, and go—none not exquisitely skilled.", idiomatic: "The emperor was filial, kind, respectful, and frugal, broadly learned and skilled in writing; yin-yang, divination, riding, archery, music, chess, clerical script, and go—none beyond him." },
  { zh: "勤於政務，冬月四更竟，即起視事，執筆觸寒，手為皴裂。", literal: "Diligent in government: in winter he finished at the fourth watch and rose to handle affairs; holding the brush in the cold, his hands cracked.", idiomatic: "He was diligent: in winter he worked until the fourth watch and rose again; in the cold his hands cracked on the brush." },
  { zh: "自天監中用釋氏法，長齋斷魚肉，日止一食，惟菜羹，糲飯而已，或遇事繁，日移中則嗽口以過。", literal: "From the Tianjian era he used Buddhist methods, long fasts without fish or meat, one meal a day of only vegetable broth and coarse rice; when affairs were numerous, past midday he rinsed his mouth and passed.", idiomatic: "From Tianjian he used Buddhist practice—long fasts without meat, one meal of vegetable broth and coarse rice; busy days he rinsed his mouth past noon and passed." },
  { zh: "身衣布衣，木綿皁帳，一冠三載，一衾二年，後宮貴妃以下，衣不曳地。", literal: "He wore cloth himself, cotton and black curtains; one cap three years, one quilt two years; consorts and below did not trail the ground in dress.", idiomatic: "He wore cloth, cotton bedding, black curtains; one cap three years, one quilt two years; consorts and below wore hems that did not touch the ground." },
  { zh: "性不飲酒，非宗廟祭祀、大饗宴及諸法事，未嘗作樂。", literal: "By nature he did not drink; except for ancestral temple sacrifice, great feasts, and legal rites, he never made music.", idiomatic: "He did not drink; except for temple sacrifice, great feasts, and rites, he never had music." },
  { zh: "雖居暗室，恆理衣冠，小坐盛暑，未嘗褰袒。", literal: "Even in a dark room he always arranged cap and robes; in small sessions even in great heat he never bared his shoulders.", idiomatic: "Even in a dark room he dressed properly; in summer heat he never bared his shoulders." },
  { zh: "對內豎小臣，如遇大賓。", literal: "Toward inner attendants and minor servants he was as toward great guests.", idiomatic: "Toward eunuchs and minor servants he was as toward great guests." },
  { zh: "然優假士人太過，牧守多浸漁百姓，使者干擾郡縣。", literal: "Yet he favored scholars too much; governors and magistrates often soaked the people; envoys harassed commanderies and counties.", idiomatic: "Yet he favored scholars too much; governors often preyed on the people; envoys harassed the districts." },
  { zh: "又好親任小人，頗復苛察。", literal: "He also liked to trust petty men personally and was rather harsh in scrutiny.", idiomatic: "He also liked to trust petty men and was harsh in scrutiny." },
  { zh: "多造塔廟，公私費損。", literal: "He built many pagodas and temples; public and private expenses were harmed.", idiomatic: "He built many pagodas and temples at great public and private cost." },
  { zh: "江南久安，風俗奢靡。", literal: "The south had been long at peace; customs were extravagant.", idiomatic: "The south had long been at peace; customs had grown extravagant." },
  { zh: "故琛啟及之。", literal: "Therefore Chen's memorial touched on it.", idiomatic: "Therefore Chen's memorial touched on it." },
  { zh: "上惡其觸實，故怒。", literal: "The emperor hated that it struck truth, and so was angry.", idiomatic: "The emperor hated that it struck truth, and was angry." },
  { zh: "臣光曰：梁高祖之不終也，宜哉！", literal: "Subject Guang says: Liang High Ancestor's not finishing his course—was it not fitting!", idiomatic: "Sima Guang comments: That Liang Gaozu did not finish his course was fitting!" },
  { zh: "夫人主聽納之失，在於叢脞；", literal: "The fault of a ruler in listening and accepting lies in clutter;", idiomatic: "A ruler's fault in listening lies in clutter;" },
  { zh: "人臣獻替之病，在於煩碎。", literal: "the illness of ministers in offering and replacing lies in fineness.", idiomatic: "ministers' fault in remonstrance lies in fineness." },
  { zh: "是以明主守要道以御萬機之本，忠臣陳大體以格君心之非。", literal: "Therefore the enlightened ruler keeps the essential way to master the root of ten thousand affairs; the loyal minister states the great body to correct what is wrong in the ruler's heart.", idiomatic: "The enlightened ruler keeps the essential way to master affairs; the loyal minister states the great body to correct the ruler's heart." },
  { zh: "故身不勞而收功遠，言至約而為益大也。", literal: "Thus the body does not toil yet harvests achievement afar; words reach only the essential yet the benefit is great.", idiomatic: "The body does not toil yet harvests far; words stay essential yet benefit is great." },
  { zh: "觀夫賀琛之諫亦未至於切直，而高祖已赫然震怒，護其所短，矜其所長；", literal: "Considering He Chen's remonstrance—it had not reached cutting directness—yet High Ancestor was already wrathfully shaken, guarding his shortcomings and boasting his strengths;", idiomatic: "He Chen's remonstrance was not even cutting, yet Gaozu was already enraged, guarding his faults and boasting his strengths;" },
  { zh: "詰貪暴之主名，問勞費之條目，困以難對之狀，責以必窮之辭。", literal: "he interrogated the names of greedy and violent lords, asked the items of labor and expense, trapped him with hard-to-answer conditions, and blamed him with words that must corner him.", idiomatic: "he demanded names of greedy lords, lists of waste, trapped him with unanswerable conditions, and blamed him into a corner." },
  { zh: "自以蔬食之儉為盛德，日昃之勤為至治，君道已備，無復可加，群臣箴規，舉不足聽。", literal: "He took vegetable eating as supreme virtue and working until sundown as utmost governance; ruler's way was already complete, nothing more could be added; ministers' admonitions were altogether not worth hearing.", idiomatic: "He took plain food for supreme virtue and sundown labor for perfect rule; in his mind the Way was complete and remonstrance worthless." },
  { zh: "如此，則自餘切直之言過於琛者，誰敢進哉！", literal: "Thus—who would dare advance blunt words sharper than Chen!", idiomatic: "Who then would dare speak blunter words than Chen!" },
  { zh: "由是奸佞居前而不見，大謀顛錯而不知，名辱身危，覆邦絕祀，為千古所閔笑，豈不哀哉！", literal: "Hence treacherous flatterers stood before him unseen, great plans toppled and erred unknown; name disgraced, body endangered, state overturned, sacrifices cut off—mocked for a thousand years: is it not pitiful!", idiomatic: "Treacherous men stood before him unseen; great plans failed unknown; disgraced, endangered, state lost, sacrifices ended—mocked for ages: pitiful!" },
  { zh: "上敦尚文雅，疏簡刑法，自公卿大臣，鹹不以鞫獄為意。", literal: "The emperor honored literature and was sparing with penal law; from dukes and ministers down, none took criminal judgment as their concern.", idiomatic: "He honored letters and was light on penal law; from ministers down, none cared about judging crime." },
  { zh: "奸吏招權弄法，貨賂成市，枉濫者多。", literal: "Crafty clerks wielded power and twisted law; bribes formed a market; the wrongly punished were many.", idiomatic: "Crafty clerks twisted law; bribes were a market; the wrongly punished were many." },
  { zh: "大率二歲刑已上歲至五千人；", literal: "Roughly, of punishments two years and up, five thousand a year reached the works;", idiomatic: "Roughly five thousand a year were sentenced to two years or more and sent to the works;" },
  { zh: "徙居作者具五任，其無任者著升械；", literal: "those sent to labor had full corvée; those without corvée wore foot shackles;", idiomatic: "those with full corvée went to labor; those without wore foot shackles;" },
  { zh: "若疾病，權解之，是後囚徒或有優、劇。", literal: "if ill, shackles were temporarily removed—after that prisoners might have light or heavy.", idiomatic: "if ill, shackles were briefly removed—after that sentences could be light or heavy." },
  { zh: "時王侯子弟，多驕淫不法。", literal: "At the time princes and marquises' sons were mostly arrogant and lawless.", idiomatic: "Princes' and marquises' sons were mostly arrogant and lawless." },
  { zh: "上年老，厭於萬幾。", literal: "The emperor was old and weary of the ten thousand affairs.", idiomatic: "The emperor was old and weary of government." },
  { zh: "又專精佛戒，每斷重罪，則終日不懌；", literal: "He also devoted himself to Buddhist precepts; whenever he cut a heavy sentence he was displeased all day;", idiomatic: "He devoted himself to Buddhist precepts; a heavy sentence displeased him all day;" },
  { zh: "或謀反逆，事覺，亦泣而宥之。", literal: "even when rebellion was discovered, he wept and pardoned.", idiomatic: "even discovered rebellion he wept and pardoned." },
  { zh: "由是王侯益橫，或白晝殺人於都街，或暮夜公行剽掠，有罪亡命者，匿於王家，有司不敢搜捕。", literal: "Thus princes and marquises grew more overbearing; some killed men in broad daylight on the capital streets, or at night openly plundered; criminals who fled hid in princes' houses and officials dared not search.", idiomatic: "Princes grew bolder; some killed in daylight on capital streets, plundered by night; fugitives hid in princes' houses and officials dared not search." },
  { zh: "上深知其弊，而溺於慈愛，不能禁也。", literal: "The emperor knew the evil deeply yet drowned in kindness and could not forbid it.", idiomatic: "He knew the evil yet drowned in kindness and could not forbid it." },
  { zh: "魏東陽王榮為瓜州刺史，與其婿鄧彥偕行。", literal: "Western Wei Prince of Dongyang Rong was governor of Guazhou and traveled with his son-in-law Deng Yan.", idiomatic: "Western Wei's Prince of Dongyang, Rong, was governor of Guazhou and traveled with his son-in-law Deng Yan." },
  { zh: "榮卒，瓜州首望表榮子康為刺史，彥殺康而奪其位。", literal: "Rong died; the leading clans of Guazhou nominated Rong's son Kang as governor; Yan killed Kang and seized his place.", idiomatic: "Rong died; Guazhou's leading clans nominated his son Kang as governor; Yan killed Kang and seized his post." },
  { zh: "魏不能討，因以彥為刺史，屢征不至，又南通吐谷渾。", literal: "Wei could not punish him and therefore made Yan governor; he was repeatedly summoned and did not come, and also opened south to Tuyuhun.", idiomatic: "Western Wei could not punish him and made him governor; repeatedly summoned, he did not come, and also allied south with Tuyuhun." },
  { zh: "丞相泰以道遠難於動眾，欲以計取之，以給事黃門侍郎申徽為河西大使，密令圖彥。", literal: "Chancellor Tai, because the road was far and hard to move the host, wished to take him by stratagem and made Attendant of the Yellow Gate Shen Hui western-route ambassador to plot against Yan secretly.", idiomatic: "Yuwen Tai, finding the road too far for an army, wished to take him by stratagem and made Shen Hui, Attendant of the Yellow Gate, western-route ambassador to plot against Yan in secret." },
  { zh: "徽以五十騎行，既至，止於賓館；", literal: "Hui traveled with fifty riders; when he arrived he stopped at the guest lodge;", idiomatic: "Hui rode with fifty men; on arrival he lodged at the guest house;" },
  { zh: "彥見徽單使，不以為疑。", literal: "Yan saw Hui as a lone envoy and did not suspect him.", idiomatic: "Yan saw a lone envoy and did not suspect him." },
  { zh: "徽遣人微勸彥歸朝，彥不從；", literal: "Hui sent men secretly to urge Yan to return to court; Yan did not follow;", idiomatic: "Hui secretly urged Yan to return to court; Yan refused;" },
  { zh: "徽又使贊成其留計，彥信之，遂來至館。", literal: "Hui again had men support his plan to stay; Yan believed them and came to the lodge.", idiomatic: "Hui again had men support his plan to remain; Yan believed them and came to the lodge." },
  { zh: "徽先與州主簿敦煌令狐整等密謀，執彥於坐，責而縛之；", literal: "Hui had already secretly plotted with the commandery recorder Dunhuang Linghu Zheng and others; they seized Yan at the seat, reproached and bound him;", idiomatic: "Hui had secretly plotted with the commandery recorder Linghu Zheng of Dunhuang and others; they seized Yan at the seat, reproached and bound him;" },
  { zh: "因宣詔慰諭吏民，且云「大軍續至」，城中無敢動者，遂送彥於長安。", literal: "then proclaimed the edict to comfort officials and people, and said \"the great army follows immediately\"; none in the city dared move, and they sent Yan to Chang'an.", idiomatic: "then proclaimed the edict to comfort officials and people and said \"the great army follows at once\"; the city dared not move, and they sent Yan to Chang'an." },
  { zh: "泰以徽為都官尚書。", literal: "Tai made Hui Minister of Justice.", idiomatic: "Yuwen Tai made Hui Minister of Justice." },
  { zh: "高祖武皇帝十五中大同元年（", literal: "Great Ancestor Emperor Wu, fifteenth year, Zhongdatong first year (", idiomatic: "Emperor Wu of Liang, fifteenth year, first year of Zhongdatong (" },
  { zh: "丙寅，公元五四六年）", literal: "bingyin, 546 CE)", idiomatic: "bingyin, AD 546)" },
  { zh: "春，正月，癸丑，楊瞟等克嘉寧城，李賁奔新昌獠中，諸軍頓於江口。", literal: "In spring, the first month, on guichou, Yang Biao and the rest took Jianing city; Li Ben fled among the Xinchang Liao; the armies camped at the river mouth.", idiomatic: "In spring, the first month, on guichou, Yang Biao and the rest took Jianing; Li Ben fled among the Xinchang Liao; the armies camped at the river mouth." },
  { zh: "二月，魏以義州刺史史寧為涼州刺史。", literal: "In the second month, Wei made Yizhou Inspector Shi Ning governor of Liangzhou.", idiomatic: "In the second month, Western Wei made Yizhou Inspector Shi Ning governor of Liangzhou." },
  { zh: "前刺史宇文仲和據州，不受代，瓜州民張保殺刺史成慶以應之，晉昌民呂興殺太守郭肆，以郡應保。", literal: "Former governor Yuwen Zhonghe held the province and would not yield; Guazhou man Zhang Bao killed Inspector Cheng Qing to respond, and Jinchang man Lü Xing killed Prefect Guo Si and joined the commandery to Bao.", idiomatic: "Former governor Yuwen Zhonghe held the province and would not yield. Guazhou's Zhang Bao killed Governor Cheng Qing in response; Jinchang's Lü Xing killed Prefect Guo Si and joined his commandery to Bao." },
  { zh: "丞相泰遣太子太保獨孤信、開府儀同三司怡峰與史寧討之。", literal: "Chancellor Tai sent Crown Prince Grand Tutor Dugu Xin and Kaifu Yitong Sansi Yi Feng with Shi Ning to punish them.", idiomatic: "Yuwen Tai sent Dugu Xin, Crown Prince Grand Tutor, and Yi Feng, Kaifu Yitong Sansi, with Shi Ning to punish them." },
  { zh: "三月，乙巳，大赦。", literal: "In the third month, on yisi, a general amnesty.", idiomatic: "In the third month, on yisi, a general amnesty." },
  { zh: "庚戌，上幸同泰寺，遂停寺省，講《三慧經》。", literal: "On gengxu the emperor visited Tongtai Temple, then stopped at the temple compound and lectured on the \"Sutra of Three Wisdoms.\"", idiomatic: "On gengxu the emperor visited Tongtai Temple, then lodged in the temple compound and lectured on the \"Sutra of Three Wisdoms.\"" },
  { zh: "夏，四月，丙戌，解講，大赦，改元。", literal: "In summer, the fourth month, on bingxu, the lecture ended; general amnesty; era name changed.", idiomatic: "In summer, the fourth month, on bingxu, the lecture ended; general amnesty; the era name was changed." },
  { zh: "是夜，同泰寺浮圖災，上曰：「此魔也，宜廣為法事。", literal: "That night the Tongtai Temple pagoda burned; the emperor said: \"This is a demon; we should widely perform the dharma.", idiomatic: "That night Tongtai Temple's pagoda burned; the emperor said: \"This is a demon—we should perform the dharma on a great scale." },
  { zh: "」群臣皆稱善。", literal: "\" The ministers all called it good.", idiomatic: "\" The ministers all approved." },
  { zh: "乃下詔曰：「道高魔盛，行善鄣生。", literal: "An edict was then issued: \"The Way is high and demons flourish; doing good meets obstruction.", idiomatic: "An edict followed: \"The Way is high and demons flourish; doing good meets obstruction." },
  { zh: "當窮茲土木，倍增往日。", literal: "We should exhaust ourselves in timber and earth, doubling what went before.", idiomatic: "Let us exhaust timber and earth, doubling what went before." },
  { zh: "」遂起十二層浮圖；", literal: "\" Thereupon a twelve-story pagoda was raised;", idiomatic: "\" A twelve-story pagoda was raised;" },
  { zh: "將成，值侯景亂而止。", literal: "when it was nearly finished, Hou Jing's rebellion came and the work stopped.", idiomatic: "and when it was nearly done, Hou Jing's rebellion stopped the work." },
  { zh: "魏史寧曉諭涼州吏民，率皆歸附，獨宇文仲和據城不下。", literal: "Wei's Shi Ning enlightened and instructed the officials and people of Liang province; all followed and submitted, save Yuwen Zhonghe, who held the city and would not yield.", idiomatic: "Shi Ning of Western Wei won over Liang province; all submitted save Yuwen Zhonghe, who held his city." },
  { zh: "五月，獨孤信使諸將夜攻其東北，自帥壯士襲其西南。", literal: "In the fifth month, Dugu Xin sent the generals to attack the northeast by night while he himself led stalwarts to strike the southwest.", idiomatic: "In the fifth month, Dugu Xin sent his generals against the northeast by night and led stalwarts himself against the southwest." },
  { zh: "遲明，克之，遂擒仲和。", literal: "At dawn they took it and captured Zhonghe.", idiomatic: "At dawn the city fell and Zhonghe was taken." },
  { zh: "初，張保欲殺州主簿令狐整，以其人望，恐失眾心，雖外相敬，內甚忌之。", literal: "At first Zhang Bao wished to kill the provincial registrar Linghu Zheng; because of his standing among men he feared losing the people's hearts, and though outwardly respectful, inwardly he greatly resented him.", idiomatic: "At first Zhang Bao wished to kill the registrar Linghu Zheng; fearing the man's standing, he feigned respect while nursing deep resentment." },
  { zh: "整陽為親附，因使人說保曰：「今東軍漸逼涼州，彼勢孤危，恐不能敵，宜急分精銳以救之。", literal: "Zheng pretended closeness and had someone say to Bao, \"Now the eastern army presses on Liangzhou; their position is isolated and perilous—they may not hold. You should quickly divide picked troops to rescue them.", idiomatic: "Zheng feigned loyalty and sent word to Bao: \"The eastern army presses Liangzhou; they stand alone and may not hold. Divide your best troops at once to save them." },
  { zh: "然成敗在於將領，令狐延保，兼資文武，使將兵以往，蔑不濟矣。", literal: "Yet victory and defeat lie with the commander. Linghu Yanbao has both civil and martial gifts—send him with troops and nothing will fail.", idiomatic: "Victory rides on the general. Linghu Yanbao has civil and martial gifts—send him with the host and you cannot fail." },
  { zh: "」保從之。", literal: "\" Bao agreed.", idiomatic: "\" Bao agreed." },
  { zh: "整行及玉門，召豪傑述保罪狀，馳還襲之。", literal: "Zheng, having reached Yumen Gate, summoned the bold spirits, set forth Bao's crimes, and galloped back to strike him.", idiomatic: "Zheng reached Yumen Gate, rallied the bold, proclaimed Bao's crimes, and galloped back to strike him." },
  { zh: "先克晉昌，斬呂興；", literal: "He first took Jinchang and beheaded Lü Xing;", idiomatic: "He took Jinchang first and beheaded Lü Xing;" },
  { zh: "進擊瓜州，州人素信服整，皆棄保來降，保奔吐谷渾。", literal: "advanced on Guazhou; the people had long trusted Zheng, all abandoned Bao and came over, and Bao fled to Tuyuhun.", idiomatic: "then marched on Guazhou; the people had long trusted Zheng, abandoned Bao, and Bao fled to Tuyuhun." },
  { zh: "眾議推整為刺史，整曰：「吾屬以張保逆亂，恐闔州之人俱陷不義，故相與討誅之；", literal: "The assembly wished to make Zheng inspector. Zheng said, \"We rose because Zhang Bao rebelled, fearing the whole province would fall into unrighteousness, and so together we punished him;", idiomatic: "The assembly would make Zheng inspector. Zheng said, \"We rose because Zhang Bao rebelled, lest the whole province sink into crime;" },
  { zh: "今復見推，是傚尤也。", literal: "now to be pushed again is to copy his fault.", idiomatic: "to accept promotion now is to copy his fault." },
  { zh: "」乃推魏所遣使波斯者張道義行州事，具以狀聞。", literal: "\" He then put forward Zhang Daoyi, whom Wei had sent as envoy to Persia, to conduct provincial affairs, and reported the full account.", idiomatic: "\" He set Zhang Daoyi, whom Western Wei had sent to Persia, to govern the province and reported all." },
  { zh: "丞相泰以申徽為瓜州刺史，召整為壽昌太守，封襄武男。", literal: "Chancellor Tai made Shen Hui inspector of Guazhou, summoned Zheng as governor of Shouchang, and enfeoffed him as Baron of Xiangwu.", idiomatic: "Yuwen Tai made Shen Hui inspector of Guazhou, summoned Zheng as governor of Shouchang, and enfeoffed him Baron of Xiangwu." },
  { zh: "整帥宗族鄉里三千餘人入朝，從泰征討，累遷驃騎大將軍、開府儀同三司，加侍中。", literal: "Zheng led more than three thousand of clan and native place into court, followed Tai on campaigns, and rose through Rapid Cavalry General, Opening the Mansion Equal in Honor to the Three Dukes, to Palace Attendant.", idiomatic: "Zheng led more than three thousand kin and neighbors to court, followed Tai on campaign, and rose to Rapid Cavalry General, Opening the Mansion Equal to the Three Dukes, and Palace Attendant." },
  { zh: "六月，庚子，東魏以司徒侯景為河南大將軍、大行台。", literal: "In the sixth month, on gengzi, Eastern Wei made Minister of Works Hou Jing Grand General of Henan and Grand Mobile Headquarters.", idiomatic: "In the sixth month, on gengzi, Eastern Wei made Hou Jing Grand General of Henan and Grand Mobile Headquarters." },
  { zh: "秋，七月，壬寅，東魏遣散騎常侍元廓來聘。", literal: "In autumn, the seventh month, on renyin, Eastern Wei sent Associate Cavalier Attendant Yuan Kuo on a friendly mission.", idiomatic: "In autumn, the seventh month, on renyin, Eastern Wei sent Yuan Kuo as envoy." },
  { zh: "甲子，詔：「犯罪非大逆，父母、祖父母不坐。", literal: "On jiazi, an edict: \"For crimes short of great treason, parents and grandparents shall not be punished.", idiomatic: "On jiazi came an edict: \"For crimes short of great treason, parents and grandparents shall not be punished." },
  { zh: "」先是，江東唯建康及三吳、荊、郢、江、湘、梁、益用錢，其餘州郡雜以谷帛，交、廣專以金銀為貨。", literal: "\" Before this, east of the river only Jiankang and the Three Wus, Jing, Ying, Jiang, Xiang, Liang, and Yi used coin; other provinces mixed grain and cloth, and Jiao and Guang used only gold and silver as currency.", idiomatic: "\" Before this, only Jiankang, the Three Wus, and Jing, Ying, Jiang, Xiang, Liang, and Yi used coin; elsewhere grain and cloth mixed, and Jiao and Guang traded in gold and silver alone." },
  { zh: "上自鑄五銖及女錢，二品並行，禁諸古錢。", literal: "The emperor himself cast wuzhu and \"female\" coins; both kinds circulated and ancient coins were forbidden.", idiomatic: "The Liang emperor cast wuzhu and \"female\" coins, let both circulate, and forbade ancient coin." },
  { zh: "普通中，更鑄鐵錢。", literal: "In the Putong era iron coin was cast anew.", idiomatic: "In the Putong era he cast iron coin anew." },
  { zh: "由是民私鑄者多，物價騰踴，交易者至以車載錢，不復計數。", literal: "Hence private casting flourished, prices soared, and traders loaded coin by the cart and no longer counted.", idiomatic: "Private casting flourished, prices soared, and traders hauled coin by the cartload without counting." },
  { zh: "又自破嶺以東，八十為百，名曰「東錢」；", literal: "Again, east of Poling, eighty counted as a hundred—called \"eastern coin\";", idiomatic: "East of Poling, eighty passed for a hundred—\"eastern coin\";" },
  { zh: "江、郢以上，七十為百，名曰：「西錢」；", literal: "above Jiang and Ying, seventy for a hundred—called \"western coin\";", idiomatic: "above Jiang and Ying, seventy for a hundred—\"western coin\";" },
  { zh: "建康以九十為百，名曰「長錢」。", literal: "Jiankang used ninety for a hundred—called \"long coin.\"", idiomatic: "Jiankang used ninety for a hundred—\"long coin.\"" },
  { zh: "丙寅，詔曰：「朝四暮三，眾狙皆喜，名實未虧而喜怒為用。", literal: "On bingyin, an edict said, \"Morning four, evening three—the monkeys are all pleased; name and substance are not diminished, yet joy and anger are wielded.", idiomatic: "On bingyin an edict said, \"Morning four, evening three—the monkeys are pleased; the sum is unchanged, yet joy and anger rule." },
  { zh: "頃聞外間多用九陌錢，陌減則物貴，陌足則物賤，非物有貴賤，乃心有顛倒。", literal: "Lately we hear the outer regions use much nine-tenths coin: when the tenth is short, goods seem dear; when the tenth is full, goods seem cheap—not that goods have high and low, but hearts are turned upside down.", idiomatic: "Lately the outer regions use short tenths: a short tenth makes goods dear, a full tenth cheap—not goods that shift, but hearts turned upside down." },
  { zh: "至於遠方，日更滋甚，徒亂王制，無益民財。", literal: "In distant places it grows worse day by day, vainly disordering royal rule and helping the people's wealth not at all.", idiomatic: "In distant places it worsens daily, disordering royal rule without helping the people's wealth." },
  { zh: "自今可通用足陌錢！", literal: "From now let full-tenth coin circulate everywhere!", idiomatic: "From now let full-tenth coin circulate everywhere!" },
  { zh: "令書行後，百日為期，若猶有犯，男子謫運，女子質作，並同三年。", literal: "After the order goes forth, a hundred days are allowed; if any still offend, men shall be sent to transport labor, women pledged to service—all for three years alike.", idiomatic: "A hundred days after the order; offenders—men to transport labor, women pledged to service—for three years alike." },
  { zh: "」詔下而人不從，錢陌益少；", literal: "\" When the edict descended the people did not obey, and coin tenths grew ever shorter;", idiomatic: "\" The edict descended and the people did not obey; tenths grew ever shorter;" },
  { zh: "至於季年，遂以三十五為百雲。", literal: "by the late years thirty-five passed for a hundred, it was said.", idiomatic: "by the late years thirty-five passed for a hundred." },
  { zh: "上年高，諸子心不相下，互相猜忌。", literal: "The emperor was advanced in years; his sons' hearts would not yield to one another, and they suspected one another.", idiomatic: "The Liang emperor was old; his sons would not yield to one another and suspected one another." },
  { zh: "邵陵王綸為丹楊尹，湘東王繹在江州，武陵王紀在益州，皆權侔人主；", literal: "Prince Lun of Shaoling was governor of Danyang, Prince Yi of Xiangdong was in Jiangzhou, Prince Ji of Wuling in Yizhou—all with power equal to a sovereign;", idiomatic: "Prince Lun of Shaoling held Danyang, Prince Yi of Xiangdong Jiangzhou, Prince Ji of Wuling Yizhou—each with power like a sovereign;" },
  { zh: "太子綱惡之，常選精兵以衛東宮。", literal: "the Crown Prince Gang hated this and constantly chose picked troops to guard the Eastern Palace.", idiomatic: "Crown Prince Gang hated this and kept picked troops to guard the Eastern Palace." },
  { zh: "八月，以綸為南徐州刺史。", literal: "In the eighth month, Lun was made inspector of South Xuzhou.", idiomatic: "In the eighth month, Lun was made inspector of South Xuzhou." },
  { zh: "東魏丞相歡如鄴。", literal: "Eastern Wei Chancellor Huan went to Ye.", idiomatic: "Gao Huan went to Ye." },
  { zh: "高澄遷洛陽《石經》五十二碑於鄴。", literal: "Gao Cheng moved fifty-two steles of the Luoyang Stone Classics to Ye.", idiomatic: "Gao Cheng moved fifty-two steles of the Luoyang Stone Classics to Ye." },
  { zh: "魏徙并州刺史王思政為荊州刺史，使之舉諸將可代鎮玉壁者。", literal: "Wei transferred Bingzhou inspector Wang Sizheng to Jingzhou and had him name generals fit to replace him in holding Yubi.", idiomatic: "Western Wei moved Wang Sizheng from Bingzhou to Jingzhou and had him name a general to hold Yubi in his stead." },
  { zh: "思政舉晉州刺史韋孝寬，丞相泰從之。", literal: "Sizheng named Jinzhou inspector Wei Xiaokuan; Chancellor Tai agreed.", idiomatic: "Sizheng named Wei Xiaokuan of Jinzhou; Yuwen Tai agreed." },
  { zh: "東魏丞相歡悉舉山東之眾，將伐魏；", literal: "Eastern Wei Chancellor Huan mustered all the hosts of Shandong to attack Wei;", idiomatic: "Gao Huan mustered all Shandong to attack Western Wei;" },
  { zh: "癸巳，自鄴會兵於晉陽；", literal: "on guisi he gathered troops at Jinyang from Ye;", idiomatic: "on guisi he gathered troops at Jinyang from Ye;" },
  { zh: "九月，至玉壁，圍之。", literal: "in the ninth month he reached Yubi and besieged it.", idiomatic: "in the ninth month he reached Yubi and besieged it." },
  { zh: "以挑西師，西師不出。", literal: "He meant to provoke the western army; the western army did not come out.", idiomatic: "He meant to draw the western army out; it did not come." },
  { zh: "李賁復帥眾二萬自獠中出屯典澈湖，大造船艦，充塞湖中。", literal: "Li Ben again led twenty thousand men out from among the Liao to camp at Dianche Lake, built many ships, and filled the lake.", idiomatic: "Li Ben again led twenty thousand from the Liao to Dianche Lake, built a fleet, and filled the lake." },
  { zh: "眾軍憚之，頓湖口，不敢進。", literal: "The allied armies feared him, halted at the lake mouth, and dared not advance.", idiomatic: "The allied armies feared him, halted at the lake mouth, and dared not advance." },
  { zh: "陳霸先謂諸將曰：「我師已老，將士疲勞；", literal: "Chen Baxian told the generals, \"Our army is worn, officers and soldiers weary;", idiomatic: "Chen Baxian told the generals, \"Our army is worn, the men weary;" },
  { zh: "且孤軍無援，入人心腹，若一戰不捷，豈望生全！", literal: "moreover we are a lone force without relief, deep in the enemy's belly—if one battle fails, who hopes to live!", idiomatic: "we stand alone without relief, deep in the enemy belly—lose one battle and who lives!" },
  { zh: "今藉其屢奔，人情未固，夷、獠烏合，易為摧殄。", literal: "Now they rely on repeated flight; hearts are not firm; Yi and Liao are a crow flock—easy to shatter.", idiomatic: "They have fled again and again; hearts are not firm; Yi and Liao are a crow flock—easy to break." },
  { zh: "正當共出百死，決力取之；", literal: "We should together stake a hundred deaths and strike with all our force;", idiomatic: "We should stake our lives together and strike with all our force;" },
  { zh: "無故停留，時事去矣！", literal: "to halt for no reason is to let the moment pass!", idiomatic: "to halt for no reason is to let the moment pass!" },
  { zh: "」諸將皆默然莫應。", literal: "\" The generals were all silent and answered not.", idiomatic: "\" The generals were silent." },
  { zh: "是夜，江水暴起七丈，注湖中。", literal: "That night the river rose seven zhang in flood and poured into the lake.", idiomatic: "That night the river rose seven zhang and poured into the lake." },
  { zh: "霸先勒所部兵乘流先進，眾軍鼓噪俱前；", literal: "Baxian drove his own troops forward on the current; the armies drummed and shouted and advanced together;", idiomatic: "Baxian drove his men forward on the flood; the armies drummed and shouted and advanced;" },
  { zh: "賁眾大潰，竄入屈獠洞中。", literal: "Ben's host broke in great rout and fled into the Qu-Liao caves.", idiomatic: "Ben's host broke and fled into the Qu-Liao caves." },
  { zh: "冬，十月，乙亥，以前東揚州刺史岳陽王察為雍州刺史。", literal: "In winter, the tenth month, on yihai, the former Eastern Yangzhou inspector, Prince Cha of Yueyang, was made inspector of Yongzhou.", idiomatic: "In winter, the tenth month, on yihai, Prince Cha of Yueyang, former inspector of Eastern Yangzhou, was made inspector of Yongzhou." },
  { zh: "上捨察兄弟而立太子綱，內常愧之，寵亞諸子。", literal: "The emperor had set aside Cha and his brothers to establish Crown Prince Gang and inwardly always felt shame toward them, favoring them next only to his sons.", idiomatic: "The Liang emperor had passed over Cha and his brothers for Crown Prince Gang and inwardly felt shame, favoring them next to his own sons." },
  { zh: "以會稽人物殷阜，故用察兄弟迭為東揚州以慰其心。", literal: "Because Kuaiji was rich in men and goods, he used Cha and his brothers in turn as Eastern Yangzhou to comfort their hearts.", idiomatic: "Because Kuaiji was rich in men and goods, he rotated Cha and his brothers through Eastern Yangzhou to comfort them." },
  { zh: "察兄弟亦內懷不平。", literal: "Cha and his brothers also nursed inward discontent.", idiomatic: "Cha and his brothers also nursed inward discontent." },
  { zh: "察以上衰老，朝多秕政，遂蓄聚貨財，折節下士，招募勇敢，左右至數千人。", literal: "Cha, seeing the emperor aged and the court full of rotten policy, then hoarded wealth, humbled himself to scholars, recruited the bold, and had several thousand at his side.", idiomatic: "Cha, seeing the emperor aged and the court rotten, hoarded wealth, humbled himself to scholars, recruited the bold, and kept several thousand at his side." },
  { zh: "以襄陽形勝之地，梁業所基，遇亂可以圖大功。", literal: "Xiangyang was a place of strategic strength, the foundation of Liang's enterprise—when disorder came, great deeds could be plotted.", idiomatic: "Xiangyang was strong ground, the foundation of Liang—when disorder came, great deeds could be plotted." },
  { zh: "乃克己為政，撫循士民，數施恩惠，延納規諫，所部稱治。", literal: "He then restrained himself in government, comforted scholars and people, often showed kindness, welcomed remonstrance, and his district was called well ruled.", idiomatic: "He governed with restraint, comforted scholars and people, showed kindness, welcomed remonstrance, and his district was called well ruled." },
  { zh: "東魏丞相歡攻玉壁，晝夜不息，魏韋孝寬隨機拒之。", literal: "Eastern Wei Chancellor Huan attacked Yubi day and night without cease; Wei's Wei Xiaokuan met him as occasion demanded.", idiomatic: "Gao Huan attacked Yubi day and night; Wei Xiaokuan of Western Wei met him as occasion demanded." },
  { zh: "城中無水，汲於汾，歡使移汾，一夕而畢。", literal: "The city had no water and drew from the Fen; Huan had the Fen diverted, and in one night it was done.", idiomatic: "The city had no water and drew from the Fen; Huan diverted the Fen, and in one night it was done." },
  { zh: "歡於城南起土山，欲乘之以入。", literal: "Huan raised an earthen hill south of the city, intending to ride it in.", idiomatic: "Huan raised an earthen hill south of the city to ride over the wall." },
  { zh: "城上先有二樓，孝寬縛木接之，令常高於土山以御之。", literal: "On the wall were already two towers; Xiaokuan bound timbers to extend them, keeping them always higher than the earthen hill to defend against it.", idiomatic: "Two towers already stood on the wall; Xiaokuan bound timbers to extend them, always keeping them higher than the hill." },
  { zh: "歡使告之曰：「雖爾縛樓至天，我當穿地取爾。", literal: "Huan sent word: \"Though you bind your towers to the sky, I shall tunnel under and take you.", idiomatic: "Huan sent word: \"Though you raise your towers to the sky, I will tunnel under and take you." },
  { zh: "」乃鑿地為十道，又用術士李業興「孤虛法」，聚攻其北。", literal: "\" He then dug ten tunnels and also used the adept Li Yexing's \"solitary and void\" method, massing attack on the north.", idiomatic: "\" He dug ten tunnels and used Li Yexing's \"solitary and void\" method, massing attack on the north." },
  { zh: "北，天險也。", literal: "The north was heaven's barrier.", idiomatic: "The north was heaven's barrier." },
  { zh: "孝寬掘長塹，邀其地道，選戰士屯塹上。", literal: "Xiaokuan dug a long moat to intercept the tunnels and chose warriors to camp on the moat.", idiomatic: "Xiaokuan dug a long moat to intercept the tunnels and posted warriors on its rim." },
  { zh: "每穿至塹，戰士輒擒殺之。", literal: "Whenever a tunnel reached the moat, the warriors seized and killed the diggers.", idiomatic: "Whenever a tunnel reached the moat, the warriors seized and killed the diggers." },
  { zh: "又於塹外積柴貯火，敵有在地道內者，塞柴投火，以皮排吹之，一鼓皆焦爛。", literal: "He also piled firewood and stored fire outside the moat; when enemies were in the tunnels, they blocked with wood, cast fire, and blew with leather bellows—at one blast all were charred.", idiomatic: "He piled firewood outside the moat; when enemies were in the tunnels, they blocked the mouths, cast fire, and blew with leather bellows—at one blast all were charred." },
  { zh: "敵以攻車撞城，車之所及，莫不摧毀，無能御者。", literal: "The enemy used battering chariots against the wall; wherever the chariots reached, nothing stood—they could not be stopped.", idiomatic: "The enemy used battering chariots; wherever they reached, the wall gave way—none could stop them." },
  { zh: "孝寬縫布為幔，隨其所向張之，布既懸空，車不能壞。", literal: "Xiaokuan sewed cloth into curtains and spread them wherever the chariots aimed; the cloth hung slack in air and the chariots could not destroy.", idiomatic: "Xiaokuan sewed cloth curtains and spread them where the chariots aimed; the cloth hung slack and the chariots could not break through." },
  { zh: "敵又縛松、麻於竿，灌油加火以燒布，並欲焚樓。", literal: "The enemy bound pine and hemp on poles, poured oil and added fire to burn the cloth, and meant also to burn the towers.", idiomatic: "The enemy bound pine and hemp on poles, poured oil, set fire to burn the cloth and the towers." },
  { zh: "孝寬作長鉤，利其刃，火竿將至，以鉤遙割之，松、麻俱落。", literal: "Xiaokuan made long hooks with sharp blades; as the fire poles neared, he cut them from afar with hooks—pine and hemp both fell.", idiomatic: "Xiaokuan made long hooks with sharp blades; as the fire poles neared, he cut them from afar—pine and hemp fell together." },
  { zh: "敵又於城四面穿地為二十道，其中施樑柱，縱火燒之。", literal: "The enemy also dug twenty tunnels on all four sides of the city, set beams and pillars within, and set them afire.", idiomatic: "The enemy dug twenty tunnels on all four sides, set beams within, and burned them." },
  { zh: "柱折，城崩。", literal: "The pillars broke and the wall collapsed.", idiomatic: "The pillars broke and the wall collapsed." },
  { zh: "孝寬隨崩處豎木柵以扞之，敵不得入。", literal: "Xiaokuan raised wooden palisades wherever it fell and held them off; the enemy could not enter.", idiomatic: "Xiaokuan raised wooden palisades wherever it fell; the enemy could not enter." },
  { zh: "城外盡攻擊之術，而城中守禦有餘。", literal: "Outside the city every art of attack was spent; inside, defense still had surplus.", idiomatic: "Every art of attack was spent outside; inside, defense still had surplus." },
  { zh: "孝寬又奪據其土山。", literal: "Xiaokuan also seized and held their earthen hill.", idiomatic: "Xiaokuan also seized their earthen hill." },
  { zh: "歡無如之何，乃使倉曹參軍祖珽說之曰：「君獨守孤城，而西方無救，恐終不能全，何不降也？", literal: "Huan could do nothing and sent Registrar of the Granary Zu Ting to persuade him, saying, \"You alone hold a lone city while the west sends no rescue—you fear you cannot hold out in the end; why not surrender?", idiomatic: "Huan could do nothing and sent Zu Ting of the granary registry to say, \"You hold a lone city and the west sends no rescue—you cannot hold out; why not surrender?" },
  { zh: "」孝寬報曰：「我城池嚴固，兵食有餘。", literal: "\" Xiaokuan replied, \"My walls are strong and firm, troops and grain abundant.", idiomatic: "\" Xiaokuan replied, \"My walls are strong, troops and grain abundant." },
  { zh: "攻者自勞，守者常逸，豈有旬朔之間已須救援！", literal: "Attackers weary themselves; defenders always rest—how could aid be needed within a ten-day month!", idiomatic: "Attackers weary themselves; defenders rest—how would I need rescue within a fortnight!" },
  { zh: "適憂爾眾有不返之危。", literal: "I only fear your host may not return.", idiomatic: "I only fear your host may not return." },
  { zh: "孝寬關西男子，必不為降將軍也！", literal: "Xiaokuan is a Guanxi man—I shall never be a surrendering general!", idiomatic: "Xiaokuan is a Guanxi man—I shall never be a surrendering general!" },
  { zh: "」珽復謂城中人曰：「韋城主受彼榮祿，或復可爾；", literal: "\" Ting again told the people in the city, \"Commandant Wei receives their honors and salary—perhaps that can be forgiven;", idiomatic: "\" Ting told the city, \"Commandant Wei takes their pay—perhaps that can be forgiven;" },
  { zh: "自外軍民，何事相隨入湯火中！", literal: "but you soldiers and civilians—why follow him into boiling water and fire!", idiomatic: "but you soldiers and civilians—why follow him into fire and boiling water!" },
  { zh: "」乃射募格於城中云：「能斬城主降者，拜太尉，封開國郡公，賞帛萬匹。", literal: "\" He then shot a recruitment notice into the city, saying, \"Who can behead the city commander and surrender shall be made Grand Commandant, enfeoffed Duke of a founding state, and given ten thousand bolts of silk.", idiomatic: "\" He shot a notice into the city: \"Behead the commander and surrender—Grand Commandant, Duke of a founding state, ten thousand bolts of silk." },
  { zh: "」孝寬手題書背，返射城外云：「能斬高歡者准此。", literal: "\" Xiaokuan wrote on the back in his own hand and shot it back outside, saying, \"Who can behead Gao Huan—same reward.", idiomatic: "\" Xiaokuan wrote on the back and shot it back: \"Behead Gao Huan—same reward." },
  { zh: "」珽，瑩之子也。", literal: "\" Ting was Ying's son.", idiomatic: "\" Ting was Ying's son." },
  { zh: "東魏苦攻凡五十日，士卒戰及病死者七萬人，共為一塚。", literal: "Eastern Wei attacked bitterly for fifty days in all; soldiers killed in battle and by sickness numbered seventy thousand, buried in one mound.", idiomatic: "Eastern Wei attacked for fifty days; seventy thousand fell in battle and sickness and were buried in one mound." },
  { zh: "歡智力皆困，因而發疾。", literal: "Huan's wit and strength were both exhausted, and he fell ill thereby.", idiomatic: "Huan's wit and strength were exhausted, and he fell ill." },
  { zh: "有星墜歡營中，士卒驚懼。", literal: "A star fell in Huan's camp; soldiers were alarmed and afraid.", idiomatic: "A star fell in Huan's camp; the soldiers were alarmed." },
  { zh: "十一月，庚子，解圍去。", literal: "In the eleventh month, on gengzi, he lifted the siege and departed.", idiomatic: "In the eleventh month, on gengzi, he lifted the siege and left." },
  { zh: "先是，歡別使侯景將兵趣齊子嶺，魏建州刺史楊檦鎮車箱，恐其寇邵郡，帥騎御之。", literal: "Before this, Huan had separately sent Hou Jing with troops toward Qizi Ridge; Wei's Jianzhou inspector Yang Biao held Chexiang, feared he would raid Shao commandery, and led cavalry to meet him.", idiomatic: "Before this, Gao Huan had sent Hou Jing toward Qizi Ridge; Yang Biao of Western Wei held Chexiang, feared a raid on Shao, and led cavalry to meet him." },
  { zh: "景聞檦至，斫木斷路六十餘里，猶驚而不安，遂還河陽。", literal: "Jing heard Biao had come, felled trees and blocked the road for more than sixty li, yet was still alarmed and uneasy, and returned to Heyang.", idiomatic: "Jing heard Biao was coming, felled trees and blocked the road for sixty li, yet remained uneasy and returned to Heyang." },
  { zh: "庚戌，歡使段韶從太原公洋鎮鄴。", literal: "On gengxu, Huan sent Duan Shao with Duke Yang of Taiyuan to guard Ye.", idiomatic: "On gengxu, Gao Huan sent Duan Shao with Duke Yang of Taiyuan to guard Ye." },
  { zh: "辛亥，征世子澄會晉陽。", literal: "On xinhai, he summoned the heir apparent Cheng to meet at Jinyang.", idiomatic: "On xinhai he summoned the heir apparent Gao Cheng to Jinyang." },
  { zh: "魏以韋孝寬為驃騎大將軍、開府儀同三司，進爵建忠公。", literal: "Wei made Wei Xiaokuan Rapid Cavalry General, Opening the Mansion Equal in Honor to the Three Dukes, and advanced his rank to Duke of Jianzhong.", idiomatic: "Western Wei made Wei Xiaokuan Rapid Cavalry General, Opening the Mansion Equal to the Three Dukes, and Duke of Jianzhong." },
  { zh: "時人以王思政為知人。", literal: "Men of the time considered Wang Sizheng one who knew men.", idiomatic: "Men of the time said Wang Sizheng knew men." },
  { zh: "十二月，己卯，歡以無功，表解都督中外諸軍，東魏主許之。", literal: "In the twelfth month, on jimao, Huan, having achieved nothing, memorialized to resign as commander-in-chief of all armies within and without; the Eastern Wei ruler permitted it.", idiomatic: "In the twelfth month, on jimao, Gao Huan, having achieved nothing, resigned command of all armies; the Eastern Wei emperor permitted it." },
  { zh: "歡之自玉壁歸也，軍中訛言韋孝寬以定功弩射殺丞相；", literal: "When Huan returned from Yubi, a rumor in the army said Wei Xiaokuan had killed the chancellor with a merit-fixed crossbow;", idiomatic: "When Gao Huan returned from Yubi, the army rumored that Wei Xiaokuan had killed the chancellor with a crossbow;" },
  { zh: "魏人聞之，因下令曰：「勁弩一發，凶身自隕。", literal: "the people of Wei heard it and thereupon ordered, \"One shot of a strong crossbow—the evil body falls of itself.", idiomatic: "Western Wei heard and ordered, \"One shot of a strong crossbow—the evil body falls." },
  { zh: "」歡聞之，勉坐見諸貴，使斛律金作《敕勒歌》，歡自和之，哀感流涕。", literal: "\" When Huan heard it, he forced himself to sit and see the nobles, had Hulu Jin compose the \"Song of the Tiele,\" joined in himself, and wept with grief moved.", idiomatic: "\" When Gao Huan heard it, he forced himself to receive the nobles, had Hulu Jin compose the \"Song of the Tiele,\" sang with him, and wept." },
  { zh: "魏大行台度支尚書、司農卿蘇綽，性忠儉，常以喪亂未平為己任，薦賢拔能，紀綱庶政；", literal: "Wei's Grand Mobile Headquarters Director of Revenue and concurrent Minister of Agriculture Su Chuo was loyal and frugal by nature, constantly took the unsettled disorders as his own charge, recommended the worthy and raised the able, and ordered the hundred affairs;", idiomatic: "Su Chuo of Western Wei's grand mobile headquarters was loyal and frugal by nature, took the unsettled realm as his charge, raised the worthy, and ordered the hundred affairs;" },
  { zh: "丞相泰推心任之，人莫能間。", literal: "Chancellor Tai entrusted him with open heart and none could come between.", idiomatic: "Yuwen Tai trusted him with an open heart and none could come between." },
  { zh: "或出遊，常預署空紙以授綽；", literal: "When he went out on tour he often pre-signed blank papers and gave them to Chuo;", idiomatic: "When he went touring he often pre-signed blank papers for Chuo;" },
  { zh: "有須處分，隨事施行，及還，啟知而已。", literal: "whatever needed disposition Chuo enacted as the matter required, and on return he merely reported—that was all.", idiomatic: "Chuo disposed as needed, and on return merely reported—that was all." },
  { zh: "綽常謂「為國之道，當愛人如慈父，訓人如嚴師。", literal: "Chuo often said, \"The way to govern a state is to love the people as a kindly father and instruct them as a stern teacher.", idiomatic: "Chuo often said, \"To govern a state is to love the people as a father and instruct them as a stern teacher." },
  { zh: "」每與公卿論議，自晝達夜，事無鉅細，若指諸掌，積勞成疾而卒。", literal: "\" Whenever he debated with the dukes and ministers, from day through night, nothing great or small but he pointed as on his palm; accumulated labor became illness and he died.", idiomatic: "\" Whenever he debated with ministers, from day through night, nothing great or small escaped him; labor piled into illness and he died." },
  { zh: "泰深痛惜之，謂公卿曰：「蘇尚書平生廉讓，吾欲全其素志，恐悠悠之徒有所未達；", literal: "Tai deeply mourned him and told the dukes and ministers, \"Director Su was modest and yielding all his life; I wish to preserve his plain intent, yet fear the idle crowd may not understand;", idiomatic: "Tai mourned him deeply and told the ministers, \"Director Su was modest all his life; I wish to preserve his plain intent, yet fear the idle crowd may not understand;" },
  { zh: "如厚加贈謚，又乖宿昔相知之心；", literal: "if I richly add posthumous gifts and titles, I again betray the heart of long acquaintance;", idiomatic: "rich posthumous gifts and titles would betray the heart of long acquaintance;" },
  { zh: "何為而可？", literal: "what can be done?", idiomatic: "what can be done?" },
  { zh: "」尚書令史麻瑤越次進曰：「儉約，所以彰其美也。", literal: "\" Secretariat clerk Ma Yao stepped forward out of order and said, \"Frugality is how one displays his excellence.", idiomatic: "\" Clerk Ma Yao stepped forward and said, \"Frugality displays his excellence." },
  { zh: "」泰從之。", literal: "\" Tai followed this.", idiomatic: "\" Tai followed this." },
  { zh: "歸葬武功，載以布車一乘，泰與群公步送出同州郭外。", literal: "He was buried at Wugong, carried on a single cloth cart; Tai and the host of lords walked to escort him beyond the outer wall of Tong province.", idiomatic: "He was buried at Wugong on a single cloth cart; Tai and the lords walked with him beyond Tong province's wall." },
  { zh: "泰於車後酹酒言曰：「尚書平生為事，妻子兄弟所不知者，吾皆知之。", literal: "Tai poured libation behind the cart and said, \"What Director did in life, what wife, children, and brothers did not know—I knew it all.", idiomatic: "Tai poured libation behind the cart and said, \"What Director did in life, unknown to wife and brothers—I knew it all." },
  { zh: "唯爾知吾心，吾知爾志，方欲共定天下，遽捨吾去，奈何！", literal: "Only you knew my heart, I knew your aim—we were just about to settle the realm together, and you suddenly leave me—what can I do!", idiomatic: "Only you knew my heart, I knew your aim—we were about to settle the realm, and you leave me—what can I do!" },
  { zh: "」因舉聲慟哭，不覺卮落於手。", literal: "\" He then raised his voice in bitter weeping, and without noticing the cup fell from his hand.", idiomatic: "\" He wept aloud, and the cup fell from his hand unheeded." },
  { zh: "東魏司徒、河南大將軍、大行台侯景，右足偏短，弓馬非其長，而多謀算。", literal: "Eastern Wei's Minister of Works, Grand General of Henan, and Grand Mobile Headquarters Hou Jing had a right foot somewhat short; bow and horse were not his strength, but he had much stratagem.", idiomatic: "Hou Jing of Eastern Wei—Minister of Works, Grand General of Henan, Grand Mobile Headquarters—had a shortened right foot; bow and horse were not his gifts, but stratagem was." },
  { zh: "諸將高敖曹、彭樂等皆勇冠一時，景常輕之，曰：「此屬皆如豕突，勢何所至！", literal: "The generals Gao Aocao, Peng Le, and others were bravest of their age; Jing often held them light and said, \"These sorts are like pigs charging—how far can their momentum go!", idiomatic: "Gao Aocao, Peng Le, and the rest were bravest of their age; Jing often held them light and said, \"These are pigs charging—how far can they go!" },
  { zh: "」景嘗言於丞相歡：「願得兵三萬，橫行天下，要須濟江縛取蕭衍老公、以為太平寺主。", literal: "\" Jing once said to Chancellor Huan, \"Give me thirty thousand troops and I will sweep the realm—I need only cross the river, bind the old man Xiao Yan, and make him abbot of Taiping Temple.", idiomatic: "\" Jing once told Gao Huan, \"Give me thirty thousand men and I will sweep the realm—cross the river, bind the old man Xiao Yan, and make him abbot of Taiping Temple." },
  { zh: "」歡使將兵十萬，專制河南，杖任若己之半體。", literal: "\" Huan had him lead a hundred thousand troops with sole rule of Henan, staff and trust like half his own body.", idiomatic: "\" Huan gave him a hundred thousand men and sole rule of Henan, staff and trust like half his body." },
  { zh: "景素輕高澄，嘗謂司馬子如曰：「高王在，吾不敢有異；", literal: "Jing had long held Gao Cheng light and once told Sima Ziru, \"While the King of Gao lives I dare not differ;", idiomatic: "Jing had long held Gao Cheng light and once told Sima Ziru, \"While the King of Gao lives I dare not differ;" },
  { zh: "王沒，吾不能與鮮卑小兒共事！", literal: "when the King is gone I cannot serve with a Xianbei stripling!", idiomatic: "when he is gone I cannot serve a Xianbei stripling!" },
  { zh: "」子如掩其口。", literal: "\" Ziru covered his mouth.", idiomatic: "\" Ziru covered his mouth." },
  { zh: "及歡疾篤，澄詐為歡書以召景。", literal: "When Huan's illness grew grave, Cheng forged Huan's hand to summon Jing.", idiomatic: "When Gao Huan's illness grew grave, Gao Cheng forged his hand to summon Jing." },
  { zh: "先是，景與歡約曰：「今握兵在遠，人易為詐，所賜書皆請加微點。", literal: "Before this, Jing and Huan had agreed, \"Now holding troops afar, men easily deceive—every letter granted, please add a small mark.", idiomatic: "Before this, Jing and Huan had agreed, \"Holding troops afar, men easily deceive—mark every letter with a small dot." },
  { zh: "」歡從之。", literal: "\" Huan agreed.", idiomatic: "\" Huan agreed." },
  { zh: "景得書無點，辭不至；", literal: "Jing received a letter without the mark and declined to come;", idiomatic: "Jing received a letter without the mark and would not come;" },
  { zh: "又聞歡疾篤，用其行台郎穎川王偉計，遂擁兵自固。", literal: "hearing also that Huan's illness was grave, he used the counsel of his mobile headquarters gentleman Wang Wei of Yingchuan and then held his troops and fortified himself.", idiomatic: "hearing Huan was grave, he took counsel from Wang Wei of Yingchuan and held his troops." },
  { zh: "歡謂澄曰：「我雖病，汝面更有餘憂，何也？", literal: "Huan said to Cheng, \"Though I am ill, your face has still more worry—why?", idiomatic: "Gao Huan said to Gao Cheng, \"Though I am ill, your face holds more worry—why?" },
  { zh: "」澄未及對，歡曰：「豈非憂侯景叛邪？", literal: "\" Before Cheng could answer, Huan said, \"Is it not fear that Hou Jing will rebel?", idiomatic: "\" Before Cheng could answer, Huan said, \"You fear Hou Jing will rebel, do you not?" },
  { zh: "」對曰：「然。", literal: "\" He answered, \"It is so.", idiomatic: "\" He answered, \"It is so." },
  { zh: "」歡曰：「景專制河南，十四年矣，常有飛揚跋扈之志，顧我能畜養，非汝所能駕御也。", literal: "\" Huan said, \"Jing has ruled Henan alone fourteen years; he has always had a soaring, overbearing will, but seeing that I could keep and nourish him—not you, who can drive him.", idiomatic: "\" Huan said, \"Jing has ruled Henan fourteen years with a soaring will; I could keep him—not you." },
  { zh: "今四方未定，勿遽發哀。", literal: "The four quarters are not yet settled—do not hasten to announce mourning.", idiomatic: "The four quarters are not settled—do not hasten to announce mourning." },
  { zh: "庫狄干鮮卑老公，斛律金敕勒老公，並性遒直，終不負汝。", literal: "Kudi Gan, the Xianbei old man, and Hulu Jin, the Tiele old man—both are forthright in nature and will never fail you.", idiomatic: "Kudi Gan, the Xianbei old man, and Hulu Jin, the Tiele old man—both are forthright and will never fail you." },
  { zh: "可朱渾道元、劉豐生，遠來投我，必無異心。", literal: "Kezhuhun Daoyuan and Liu Fengsheng came from afar to join me—they surely have no other heart.", idiomatic: "Kezhuhun Daoyuan and Liu Fengsheng came from afar—they have no other heart." },
  { zh: "潘相樂本作道人，心和厚，汝兄弟當得其力。", literal: "Pan Xiangle was originally a Taoist; his heart is mild and thick—you brothers should gain his strength.", idiomatic: "Pan Xiangle was once a Taoist, mild and thick—you brothers should gain his strength." },
  { zh: "韓軌少戇，宜寬借之。", literal: "Han Gui is somewhat dull in youth—you should treat him generously.", idiomatic: "Han Gui is somewhat dull—treat him generously." },
  { zh: "彭樂心腹難得，宜防護之。", literal: "Peng Le's inner heart is hard to win—you should guard and protect him.", idiomatic: "Peng Le's heart is hard to win—guard him." },
  { zh: "堪敵侯景者，唯有慕容紹宗，我故不貴之，留以遺汝。", literal: "The one who can match Hou Jing is only Murong Shaozong; I therefore did not honor him highly, but left him for you.", idiomatic: "Only Murong Shaozong can match Hou Jing; I did not honor him, but left him for you." },
  { zh: "」又曰：「段孝先忠亮仁厚，智勇兼備，親戚之中，唯有此子，軍旅大事，宜共籌之。", literal: "\" He also said, \"Duan Xiaoxian is loyal, bright, humane, and thick, with wisdom and courage together—in kin, only this son; great military affairs, you should plan together.", idiomatic: "\" He also said, \"Duan Xiaoxian is loyal, humane, wise, and brave—in kin, only this son; on great military affairs, plan together." },
  { zh: "」又曰：「邙山之戰，吾不用陳元康之言，留患遺汝，死不瞑目！", literal: "\" He also said, \"At the battle of Mount Mang I did not use Chen Yuankang's counsel and left trouble for you—I cannot close my eyes in death!", idiomatic: "\" He also said, \"At Mount Mang I ignored Chen Yuankang and left trouble for you—I cannot close my eyes in death!" },
  { zh: "」相樂，廣寧人也。", literal: "\" Xiangle was a man of Guangning.", idiomatic: "\" Xiangle was a man of Guangning." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
